import{_ as l,h as r,i as e,c as i,v as t,p as s,x as n,m as h,e as d,S as p}from"./chunks/framework.Dvtg8yj2.js";const y=JSON.parse('{"title":"Hyena","description":"","frontmatter":{"title":"Hyena","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/hyena.md","filePath":"llm/hyena.md","lastUpdated":1788454257000}'),m={name:"llm/hyena.md"};function F(E,a,c,_,u,T){const o=r("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="hyena" tabindex="-1">Hyena <a class="header-anchor" href="#hyena" aria-label="Permalink to &quot;Hyena&quot;">​</a></h1><div class="epigraph"><p>注意力是数据控制的稠密矩阵；Hyena 用隐式长卷积与逐元门控的递推去因子化同一类算子，次二次求值，参数不随长度涨。</p><footer>—— Poli et al., Hyena Hierarchy: Towards Larger Convolutional Language Models, ICML 2023</footer></div><p>次二次层要追上注意力，低秩或稀疏往往还得混回若干稠密注意力头。Poli、Massaroli、Nguyen、Fu、Dao 等人 2023 年的 Hyena 不走逼近 softmax 的路，而是直接构造一个<strong>数据控制的线性算子</strong>，使其矩阵形式是对角门控与 Toeplitz 卷积的交替乘积。算子由「隐式参数化的长卷积 + 逐元门控」递推定义，阶数（order）控制因子个数。短阶时覆盖 <a href="/llm/h3">H3</a> 一类特殊情形；更长的阶给出更大的数据控制矩阵，而不物化 \\(L\\times L\\) 的注意力表。求值用 FFT 卷积，\\(O(L\\log L)\\)。在数千到数十万长度的推理任务上，Hyena 相对纯 SSM / 传递函数算子可高出五十多个点，并在 WikiText103 与 The Pile 上达到当时无稠密注意力架构的最好质量，2k 长度训练算力约省 20%，8k 上比高度优化的注意力快约 2 倍、64k 上可达约 100 倍。本篇写 Hyena 算子本身，不把后续 HyenaDNA 的基因组实验展开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>注意力对输入 \\(u\\) 形成一个矩阵 \\(A(u)\\)，再乘值。\\(A(u)\\) 的每个元素都可以依赖整段 \\(u\\)，这是「 unrestricted context」；代价是 \\(O(L^2)\\)。次二次方法若只近似 \\(A(u)\\) 的低秩或稀疏图案，会在需要密集数据控制的推理任务上崩——论文用这类任务当过滤器：过不了过滤器的算子，放大之后也很难只靠宽度补回来。</p><p>H3 已经表明：长卷积加一两次乘法，能补上 SSM 的联想回忆。下一步是：把「门控–卷积」当成可堆叠的因子，而不是固定的两层 SSM；并且卷积核不要存 \\(L\\) 个 tap（那会让参数随长度线性涨），而要用一个小网络从位置映射到滤波器，即隐式参数化。目标是 drop-in 替换注意力：输入输出形状不变，复杂度亚二次，参数亚线性于 \\(L\\)，且不必与 softmax 层杂交。<span class="marginnote">「数据控制」指矩阵元素是输入的函数。卷积本身不是数据控制的——同一条 \\(h\\) 扫所有样本。Hyena 的控制来自门控对角阵，卷积只提供平移等变的长程混合。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="阶为-的-hyena-算子" tabindex="-1">阶为 \\(N\\) 的 Hyena 算子 <a class="header-anchor" href="#阶为-的-hyena-算子" aria-label="Permalink to &quot;阶为 $N$ 的 Hyena 算子&quot;">​</a></h3><p>将输入投影成 \\(v,x^1,\\ldots,x^N\\) 共 \\(N+1\\) 路，并学习滤波器 \\(h^1,\\ldots,h^N\\)。递推为</p> \\[z^1 = v,\\qquad z^{n+1}_t = x^n_t \\odot (h^n * z^n)_t,\\qquad y = z^{N+1}. \\]<p>\\(h^n * z^n\\) 是因果长卷积。矩阵语言里，每一步左乘一个对角阵 \\(D_{x^n}\\)（由 \\(x^n\\) 填对角）和一个 Toeplitz 阵 \\(T_{h^n}\\)。整个算子是</p> \\[y = D_{x^N} T_{h^N}\\cdots D_{x^1} T_{h^1} v, \\]<p>一张数据控制的 \\(L\\times L\\) 矩阵的因子化，求值时绝不把该矩阵展开。阶 \\(N=2\\) 时已接近 H3 的「门、长混合、门」骨架；更大的 \\(N\\) 增加因子深度，也增加投影路数。</p><h3 id="隐式滤波器-参数与长度解耦" tabindex="-1">隐式滤波器：参数与长度解耦 <a class="header-anchor" href="#隐式滤波器-参数与长度解耦" aria-label="Permalink to &quot;隐式滤波器：参数与长度解耦&quot;">​</a></h3><p>\\(h\\) 不存成长度为 \\(L\\) 的向量。一个小 FFN（或 SIREN 一类）吃位置特征——\\(\\sin,\\cos\\)、归一化时间、常数项——输出该位置的滤波器值。参数量与 \\(L\\) 无关，上下文在长度上不受限，这一点与注意力相同。求值仍用 FFT：\\(h\\) 先被物化成长度 \\(L\\) 的核（或按块），再 \\(\\mathrm{FFT}^{-1}(\\mathrm{FFT}(h)\\odot\\mathrm{FFT}(z))\\)。因果通过把核与信号补零或使用因果 FFT 约定保证。</p><p>短卷积常加在投影上，先抽局部特征再进长程 Hyena，避免长核去拟合本该由 3–5 阶 FIR 完成的邻域。论文把滤波器参数化列为影响最大的设计选择之一：同样是长卷积，隐式核比对角 SSM 的传递函数更容易学到需要的长阶响应。</p><h3 id="不杂交注意力的缩放证据" tabindex="-1">不杂交注意力的缩放证据 <a class="header-anchor" href="#不杂交注意力的缩放证据" aria-label="Permalink to &quot;不杂交注意力的缩放证据&quot;">​</a></h3><p>此前次二次模型要在尺度上对齐 Transformer，往往插入稠密注意力层。Hyena 的主张是：过滤器任务上已经匹配注意力后，纯卷积语言模型可以在标准语料上靠近 Transformer 质量。The Pile / WikiText103 上的结果用来支持「不是玩具长度上的巧合」。速度数字绑定在当时的注意力实现与长度上：长度越长，FFT 相对 \\(L^2\\) 越明显；短于 2k 时优势缩小，与所有亚二次方法一致。<span class="marginnote">隐式核在每一步都被物化成长度 \\(L\\) 的 \\(h\\)。省的是参数不是这 \\(L\\) 个数的计算。若 FFN 在每个时间步、每个通道都用未融合的 MLP 现场算 \\(h\\)，生成核的时间会压过 FFT 本身。</span></p>',18)),(e(),s(p,null,{default:n(()=>[d(o,{id:"mermaid-48",class:"mermaid",graph:"flowchart%20TD%0A%20%20U%5B%22%E8%BE%93%E5%85%A5%20u%22%5D%20--%3E%20P%5B%22N%2B1%20%E8%B7%AF%E6%8A%95%E5%BD%B1%22%5D%0A%20%20P%20--%3E%20V%5B%22v%22%5D%0A%20%20P%20--%3E%20X%5B%22%E9%97%A8%E6%8E%A7%20x%5E1..x%5EN%22%5D%0A%20%20F%5B%22%E4%BD%8D%E7%BD%AE%20FFN%22%5D%20--%3E%20H%5B%22%E9%9A%90%E5%BC%8F%E6%A0%B8%20h%22%5D%0A%20%20V%20--%3E%20C%5B%22%E5%9B%A0%E6%9E%9C%20FFT%20%E5%8D%B7%E7%A7%AF%22%5D%0A%20%20H%20--%3E%20C%0A%20%20X%20--%3E%20G%5B%22%E9%80%90%E5%85%83%E9%97%A8%E6%8E%A7%22%5D%0A%20%20C%20--%3E%20G%0A%20%20G%20--%3E%20C%0A%20%20G%20--%3E%20Y%5B%22%E8%BE%93%E5%87%BA%20y%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>注意力的 \\(A(u)_{ij}\\) 可以直接是 \\(q_i^\\top k_j\\)。Hyena 的等价矩阵每个元素是若干门控与卷积系数的多项式型组合，感受野仍是全局的（因果下三角），但交互必须通过这条因子链。表达力来自：门控让不同样本走不同的有效卷积；长核让远处的 \\(v\\) 仍能进来；多阶让「先比较再混合再比较」成为可能，这正是 H3 诊断里联想回忆需要的乘法深度。</p><p>与 SSM 的差别主要在参数化。对角 SSM 的核是指数模态的叠加，衰减形状受极点约束；Hyena 的核由 FFN 自由生成，可以更尖、更振荡，也更容易过拟合到训练长度上的伪周期。这是 64k 加速好看、外推长度时要重新生成 \\(h\\) 的原因：位置特征里若含 \\(t/L_{\\mathrm{train}}\\)，测试长度一变，核的形状会变。</p><p>数值上 FFT 卷积对精度敏感，半精度下应用 FP32 累加或拆成实部更高精度。因果掩码不能事后乘在 \\(L\\times L\\) 矩阵上——那张矩阵不存在——必须在核的支撑与前缀填充上保证。训练并行（整段卷积）与推理逐步（线性递推或滑动 FFT）需要同一条核；推理若改成截断 FIR，等于改了算子。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>Hyena 替换的是注意力算子，不是整个块：FFN、残差、归一化仍在。精确、任意位置的内容寻址仍可能弱于 softmax，极端针测不要只看 Pile 的损失。阶 \\(N\\) 加大线性增加投影与卷积次数，3 左右是论文常用区，再深未必值得。</p><p>硬件上，FFT 与 GEMM 的屋顶线不同。FlashAttention 把 \\(L^2\\) 的常数压得很低之后，Hyena 的交叉点向更长的 \\(L\\) 移动。部署前要在目标长度测，不能引用 2023 年 8k/64k 的倍速当作今天的数字。与 <a href="/llm/mamba">Mamba</a> 比：Mamba 走选择性扫描与 SRAM 友好的递推；Hyena 走 FFT 与隐式核。长卷积生态的融合核少于 Mamba 的 scan，工程成熟度是真实约束。</p><p>隐式 FFN 的位置编码不要和 RoPE 混用在同一条 \\(x\\) 上而不做消融：一个在投影空间旋转内容，一个在滤波器空间看绝对/相对时间，失败模式缠在一起。<span class="marginnote">「100× at 64k」比较的是算子墙钟，假设实现合理且 batch 能喂满设备。单请求、短解码步上，FFT 的启动开销可能让递推 SSM 反而更合适。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Hyena 用隐式长卷积与门控的递推，因子化数据控制的线性算子，作为注意力的亚二次替换。</li><li>参数由位置 FFN 生成核，不随 \\(L\\) 线性增长；求值 \\(O(L\\log L)\\)。</li><li>低阶包含 H3 类结构；更高阶增加乘法–卷积深度，无需杂交 softmax。</li><li>过滤器任务与 Pile 上的质量用来说明能力缺口被缩小，而不是低秩逼近碰巧过了语言建模。</li><li>核的隐式参数化是双刃剑：表达力强，长度外推与 FFT 数值要单独管。</li><li>短序列与未融合实现上不一定快；交叉点随注意力内核成熟度右移。</li><li>出处：Poli et al., <em>Hyena Hierarchy: Towards Larger Convolutional Language Models</em>, ICML 2023。</li></ul>',10))])}const x=l(m,[["render",F]]);export{y as __pageData,x as default};
